using FarmWorking.Application.Abstractions; using FarmWorking.Domain.Entities; using FarmWorking.Domain.Enums; using FarmWorking.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace FarmWorking.Infrastructure.Repositories;
public class SupplyRepository(FarmDbContext db):ISupplyRepository{public IReadOnlyList<Supply> GetAll(SupplyType? type=null)=>db.Supplies.AsNoTracking().Where(x=>type==null||x.Type==type).OrderBy(x=>x.Name).ToList();public Supply? Find(Guid id)=>db.Supplies.Find(id);public int CountLowStock()=>db.Supplies.Count(x=>x.Quantity<=x.MinimumStock);public void Add(Supply item)=>db.Supplies.Add(item);public void Remove(Supply item)=>db.Supplies.Remove(item);public Task SaveChangesAsync(CancellationToken ct=default)=>db.SaveChangesAsync(ct);}
